mapper.select:
select orders.*, goods.name as goodsName, goods.img as goodsImg, user.name as userName, address.consignee as consignee, address.phone as phone, address.province as province, address.city as city, address.district as district, address.detail as addressDetail,
CONCAT(address.consignee, ' ', address.phone, ' ', address.province, address.city, address.district, address.detail) as addressInfo,
goods.price as price, (goods.price * orders.num) as total, goods.specials as specials, goods.unit as unit from orders left join goods on orders.goods_id = goods.id left join user on orders.user_id = user.id left join address on orders.address_id = address.id
and order_no like concat('%', #{orderNo}, '%') and goods.name like concat('%', #{goodsName}, '%') and user.name like concat('%', #{userName}, '%') and status = #{status}
and orders.user_id = #{userId}
order by orders.id desc

select orders.*, goods.name as goodsName, goods.img as goodsImg, user.name as userName, address.consignee as consignee, address.phone as phone, address.province as province, address.city as city, address.district as district, address.detail as addressDetail,
CONCAT(address.consignee, ' ', address.phone, ' ', address.province, address.city, address.district, address.detail) as addressInfo,
goods.price as price, (goods.price * orders.num) as total, goods.specials as specials, goods.unit as unit from orders left join goods on orders.goods_id = goods.id left join user on orders.user_id = user.id left join address on orders.address_id = address.id where orders.id = #{id}
